def backfill_retainers(apps, schema_editor):
    """Give existing retainers a start date and record paid monthly invoices as paid months."""
    Project = apps.get_model("crm", "Project")
    Invoice = apps.get_model("crm", "Invoice")
    RetainerPayment = apps.get_model("crm", "RetainerPayment")
    for p in Project.objects.filter(billing_type__in=["monthly", "both"]):
        monthly = Invoice.objects.filter(project=p, kind="monthly").exclude(status="void").exclude(period_start=None)
        first = monthly.order_by("period_start").values_list("period_start", flat=True).first()
        start = first or p.next_invoice_date
        if start:
            p.retainer_start = start
            p.save(update_fields=["retainer_start"])
        for inv in monthly.filter(status="paid"):
            total = sum((i.quantity * i.unit_price for i in inv.items.all()), 0)
            RetainerPayment.objects.get_or_create(
                project=p, period_start=inv.period_start,
                defaults={"amount": total, "invoice": inv, "paid_on": (inv.paid_at or inv.created_at).date()},
            )


